module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
        end
        else begin
            case (state)
                2'b00: state <= 2'b01;
                2'b01: state <= 2'b10;
                2'b10: state <= 2'b00;
                default: state <= 2'b00;
            endcase
        end
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] current_state, next_state;

    always @(*) begin
        case (current_state)
            2'b00: next_state = 2'b01;
            2'b01: next_state = 2'b10;
            2'b10: next_state = 2'b00;
            default: next_state = 2'b00;
        endcase
    end

    always @(posedge clk or posedge reset) begin
        if (reset) 
            current_state <= 2'b00;
        else 
            current_state <= next_state;
    end

    assign state = current_state;
endmodule

