);
parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10;
reg [1:0] current_state, next_state;

always @(posedge clk, posedge reset) begin
    if (reset) current_state <= S0;
    else current_state <= next_state;
end

always @(*) begin
