module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] light;
    reg [3:0] counter;
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            counter <= 0;
            light <= 3'b100;
        end
        else begin
            if (counter == 4'd13) begin
                counter <= 0;
                light <= 3'b010;
            end
            else if (counter == 4'd5) begin
                counter <= 0;
                light <= 3'b001;
            end
            else if (counter == 4'd9) begin
                counter <= 0;
                light <= 3'b100;
            end
            else begin
                counter <= counter + 1;
                light <= light;
            end
        end
    end
endmodule

