module traffic_light (
    input clk, reset,
    output [2:0] light
);
    parameter MODE_COUNT = 600;

    reg [1:0] state;
    reg [10:0] count;
    reg [2:0] light_value;

    wire [1:0] next_state;
    wire [2:0] next_light_value;
    wire valid_cnt = count > 0;

    assign next_state = (state == 2'b00) ? 2'b01 : (state == 2'b01) ? 2'b10 : 2'b11;
    assign next_light_value = (state == 2'b00) ? 3'b001 : (state == 2'b01) ? 3'b010 : (state == 2'b10) ? 3'b100 : 3'b000;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            count <= 0;
            state <= 2'b00;
        end else if (valid_cnt && count <= MODE_COUNT) begin
            count <= count + 1;
        end else begin
            state <= next_state;
            count <= 0;
        end
    end

    assign light = (count <= MODE_COUNT) ? 3'b000 : light_value;
endmodule

