module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] light;
    reg [4:0] count;
    parameter [4:0] COUNT_TO_5_SEC = 30_000_000;
    always @(posedge clk) begin
        if (reset) begin
            count <= 0;
            light <= 3'b000;
        end
        else if (count < COUNT_TO_5_SEC) begin
            count <= count + 1;
        end
        else begin
            count <= 0;
            light <= {light[0], light[1], light[2]};
        end
    end
endmodule

