module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] state_reg, state_next;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= 2'b00;
        end else begin
            state_reg <= state_next;
        end
    end

    always @(*) begin
        state_next = state_reg;

        case (state_reg)
            2'b00: begin
                if (up_request & ~down_request) begin
                    state_next = 2'b01;
                end else if (~up_request & down_request) begin
                    state_next = 2'b10;
                end
            end
            2'b01: begin
                if (up_request & ~down_request) begin
                    state_next = 2'b01;
                end else if (~up_request & down_request) begin
                    state_next = 2'b10;
                end
            end
            2'b10: begin
                if (up_request & ~down_request) begin
                    state_next = 2'b01;
                end else if (~up_request & down_request) begin
                    state_next = 2'b10;
                end
            end
        endcase
    end

    assign state = state_reg;
endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] next_state;
    reg [1:0] current_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= 2'b00;
        end else begin
            current_state <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;
        if (current_state == 2'b00 && up_request) begin
            next_state = 2'b01;
        end else if (current_state == 2'b01 && down_request) begin
            next_state = 2'b10;
        end else if (current_state == 2'b10 && down_request) begin
            next_state = 2'b11;
        end else if (current_state == 2'b11 && up_request) begin
            next_state = 2'b00;
        end else if (current_state == 2'b01 && up_request) begin
            next_state = 2'b00;
        end
    end

    assign state = current_state;
endmodule

