module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] state;
    reg [1:0] next_state;
    reg [1:0] coin_count;

    always @(*) begin
        next_state = state;
        coin_count = coin_count;
        case (state)
            2'd0: begin
                if (coin_inserted) next_state = 2'd1;
                else next_state = 2'd0;
            end
            2'd1: begin
                if (!item_selected) next_state = 2'd1;
                else next_state = 2'd0;
            end
        endcase
    end

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'd0;
            coin_count <= 2'd0;
        end
        else begin
            state <= next_state;
            coin_count <= coin_count + coin_inserted;
        end
    end

    assign state = state;
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] state, next_state;
    reg [2:0] coins_inserted;
    reg item_dispensed;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
            coins_inserted <= 3'b000;
            item_dispensed <= 1'b0;
        end
        else begin
            state <= next_state;
            coins_inserted <= coins_inserted + coin_inserted;
            item_dispensed <= item_dispensed | item_selected;
        end
    end

    always @(*) begin
        next_state = state;
        case (state)
             2'b00: begin
                if (coin_inserted) begin
                    next_state = 2'b01;
                end
                else begin
                    next_state = 2'b00;
                end
            end
            2'b01: begin
                if (coins_inserted >= 3) begin
                    next_state = 2'b10;
                    if (item_selected) begin
                        next_state = 2'b11;
                    end
                end
                else begin
                    next_state = 2'b01;
                end
            end
            2'b10: begin
                if (item_selected) begin
                    next_state = 2'b11;
                end
                else begin
                    next_state = 2'b10;
                end
            end
            2'b11: begin
                if (item_selected) begin
                    next_state = 2'b11;
                end
                else begin
                    next_state = 2'b10;
                end
            end
        endcase
    end

    assign state = next_state;
endmodule

