module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    wire [7:0] left, right, f_out;
    wire [7:0] xor_result;

    assign left = data_in[7:4];
    assign right = data_in[3:0];

    // S-Box for the right half of the data
    assign f_out = {
        3'b111,  // S-Box output for the first two bits of right
        3'b000,  // S-Box output for the next two bits of right
        3'b001,  // S-Box output for the next two bits of right
        2'b11   // S-Box output for the last two bits of right
    };

    assign xor_result = right ^ f_out;

    assign data_out = {left, xor_result};
endmodule

