    input wire rst,
    output wire [7:0] count
);

wire [7:0] counter_value;
wire [7:0] ones;
wire [7:0] count_reg;

assign ones = 1'b1 << count_reg;

assign counter_value = count_reg;

always @ (posedge clk) begin
    if (rst) begin
        count_reg <= 8'd0;
    end 
    else if (count_reg < 8'd255) begin
        count_reg <= count_reg + 1;
    end 
    else begin
        count_reg <= count_reg - 1;
    end
end

assign count = count_reg;
endmodule

