module TopModule (
  input clk,
  input w,
  input R,
  input E,
  input L,
  output reg Q
);
always @(*) begin
  case (w)
    0: Q = (R & E) | (L ^ E);
    1: Q = (R & ~E) | (L & E);
    default: Q = 1'b0;
  endcase
end
endmodule

