    if (R) begin
      a <= 5'b00010;
      b <= 5'b00100;
      c <= 5'b01000;
    end
    else if (E) begin
      a <= 5'b00100;
      b <= 5'b01000;
      c <= 5'b10000;
    end
    else if (L) begin
      a <= 5'b10000;
      b <= 5'b00000;
      c <= 5'b00000;
    end
    else if (w) begin
      a <= 5'b00100;
      b <= 5'b01000;
      c <= 5'b10000;
    end
  end
  always @(posedge clk) begin
    Q <= a & b & c;
  end
