  wire [1:0] comp2_next;
  wire [1:0] comp3_next;
  reg [1:0] comp3_q;
  wire comp1_fall;
  wire comp2_fall;
  wire x;
  reg [1:0] dr;
  wire [1:0] d; numbers;
  wire [1:0] comp4_next;

  always @(posedge clk) begin
