      state <= 2'b00;
      q <= 1'b0;
      comp1_q <= 2'b00;
      comp2_q <= 2'b00;
      comp3_q <= 2'b00;
      dr <= 2'b00;
    end else begin
      state <= comp1_next;
      q <= comp2_next;
      comp1_q <= comp1_fall ? comp2_next : comp1_q;
      comp2_q <= state;
      comp3_q <= comp3_next;
      dr <= comp4_next;
      x <= comp3_q;
    end
  end

  assign comp1_fall = comp1_q[0] & ~comp1_q[1];
  assign comp2_fall = comp2_q[0] & ~comp2_q[1];
  assign x = comp3_q;
  assign z = x & w;

  always @(*) begin
    comp1_next = 2'b00;
    comp2_next = 2'b00;
    comp3_next = 2'b00;
    comp4_next = 2'b00;
    numbers = 2'b00;
    d = 2'b00;

    unique case (state) 
      2'b00: 
        if (~comp1_fall) 
          state <= 2'b00;
        else if (comp2_fall) 
          state <= 2'b01;
        else 
          state <= 2'b10;
      2'b01: 
        if (comp2_fall | comp1_fall) 
          state <= 2'b00;
        else 
          state <= 2'b01;
      2'b10: 
        if (comp3_fall & comp2_fall) 
          state <= 2'b00;
        else if (comp1_fall) 
          state <= 2'b11;
        else 
          state <= 2'b10;
      2'b11: 
        if (~comp2_fall) 
          state <= 2'b11;
        else 
          state <= 2'b00;
      default: 
        state <= 2'b00;
    endcase

    if (comp1_fall) 
      comp2_next = 2'b01;
    else if (comp2_fall) 
      comp2_next = 2'b11;
    else 
      comp2_next = 2'b00;

    if (comp1_fall) 
      comp3_next = 2'b01;
    else if (comp2_fall) 
      comp3_next = 2'b11;
    else 
      comp3_next = 2'b00;

    if (comp1_fall & ~comp2_fall) 
      comp4_next = 2'b01;
    else if (comp2_fall & ~comp1_fall) 
      comp4_next = 2'b10;
    else 
      comp4_next = 2'b00;

    if (comp1_fall & ~comp2_fall) 
      numbers = 2'b01;
    else if (comp2_fall & ~comp1_fall) 
      numbers = 2'b10;
    else 
      numbers = 2'b00;
  end

  assign comp3_next = numbers;
  assign comp4_next = d;

  assign d = (~dr[1] & dr[0]) | (dr[1] & ~dr[0]);
