    s = 4'b0;
    if (n_state == 4'b0001) s <= a ? 4'b0010 : 4'b0000;
    if (n_state == 4'b0010) s <= a ? 4'b0011 : 4'b0000;
    if (n_state == 4'b0011) s <= b ? 4'b0100 : 4'b0000;
    if (n_state == 4'b0100) s <= 4'b0000;
