module TopModule (
  input clk,
  input reset,
  input in,
  output disc,
  output flag,
  output err
);

  reg [3:0] state;
  reg [3:0] count;
  reg local_disc;
  reg local_flag;
  reg local_err;

  assign disc = local_disc;
  assign flag = local_flag;
  assign err = local_err;

  always @(posedge clk) begin
    if (reset) begin
      state <= 4'h0;
      count <= 4'h0;
      local_disc <= 1'b0;
      local_flag <= 1'b0;
      local_err <= 1'b0;
    end
    else begin
      case (state)
        4'h0: begin
          if (in) begin
            state <= 4'h1;
          end
          else begin
            state <= 4'h0;
          end
        end
        4'h1: begin
          if (in) begin
            state <= 4'h2;
          end
          else begin
            state <= 4'h0;
          end
        end
        4'h2: begin
          if (in) begin
            count <= 4'h1;
          end
          else begin
            state <= 4'h0;
          end
        end
        4'h3: begin
          if (count < 4'h3) begin
            count <= count + 1;
          end
          else begin
            local_disc <= 1'b1;
            local_flag <= 1'b0;
            local_err <= 1'b0;
            state <= 4'h0;
          end
        end
      endcase
    end
  end

endmodule

