  reg [3:0] count;
  reg done_signal;

  always @(posedge clk) begin
    if (reset) begin
      count <= 4'b0000;
      done_signal <= 1'b0;
    end
    else begin
      if (in) begin
        if (count == 4'b1111) begin
          count <= 4'b0000;
          done_signal <= 1'b1;
        end
        else begin
          count <= count + 4'b0001;
          done_signal <= 1'b0;
        end
      end
      else begin
        count <= 4'b0000;
        done_signal <= 1'b0;
      end
    end
  end

  assign done = done_signal;

endmodule

