		input done_counting,
		input ack,
		input [9:0] state, // 10-bit one-hot current state
		output B3_next,
		output S_next,
		output S1_next,
		output Count_next,
		output Wait_next,
		output done,
		output counting,
		output shift_ena
		);
		always_comb begin
		done = (state[1] && ack) | (state[0] && done_counting);
		counting = state[3] | state[4];
		shift_ena = state[5];
		Wait_next = state[6];
		Count_next = state[7];
		S1_next = state[8];
		S_next = state[9];
		B3_next = state[0];
		end
		endmodule
	]

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  assign counting = (state == 10'd2) | (state == 10'd3) | (state == 10'd4) | (state == 10'd5) | (state == 10'd6) | (state == 10'd7) | (state == 10'd8) | (state == 10'd9) | (state == 10'd10) | (state == 10'd11);
  assign shift_ena = (state == 10'd3) | (state == 10'd4) | (state == 10'd5) | (state == 10'd6) | (state == 10'd7) | (state == 10'd8) | (state == 10'd9) | (state == 10'd10) | (state == 10'd11) | (state == 10'd12);
  assign count_next = (state == 10'd1) | (state == 10'd2) | (state == 10'd3) | (state == 10'd4) | (state == 10'd5) | (state == 10'd6) | (state == 10'd7) | (state == 10'd8) | (state == 10'd9) | (state == 10'd10) | (state == 10'd11) | (state == 10'd12) | (state == 10'd13) | (state == 10'd14) | (state == 10'd15) | (state == 10'd16) | (state == 10'd17) | (state == 10'd18);
  assign wait_next = !(d) & !ack;
  assign B3_next = (state == 10'd0) & ack;
  assign done = done_counting & state == 10'd0;
  assign S_next = !S1_next & !done & (wait_next | counting);
  assign S1_next = d & !S_next;

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);
  // assign to wire or logic type outputs if no if/else or case used below
  assign B3_next = state[1];
  assign S_next = state[2];
  assign S1_next = state[3];
  assign Count_next = state[4];
  assign Wait_next = state[5];
  assign done = (state[8] & done_counting) | state[9];
  assign counting = state[6];
  assign shift_ena = state[7];
endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

