    assign carry[0] = (a[0] & b[0]) | (b[0] & cin) | (a[0] & cin);

    generate
        genvar i;
        for (i = 1; i < 8; i = i + 1) begin : inner_loop
            assign sum[i] = a[i] ^ b[i] ^ carry[i-1];
            assign carry[i] = (a[i] & b[i]) | (b[i] & carry[i-1]) | (a[i] & carry[i-1]);
        end
    endgenerate

    assign cout = carry[7];
