module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [15:0] count;
    always @ (posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            count <= 0;
            clk_div <= 0;
        end
        else begin
            if (count == 0) begin
                count <= 0;
                clk_div <= ~clk_div;
            end
            else if (count <= (NUM_DIV * 2) - 1) begin
                count <= count - 1;
            end
            else begin
                count <= count - 1;
            end
        end
    end
