module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [3:0] shift_reg;
    reg [2:0] count_reg;
    wire valid_out_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_reg <= 4'b0000;
            count_reg <= 3'b000;
        end
        else begin
            count_reg <= count_reg;
            if (count_reg == 3'd2) begin
                shift_reg <= d;
            end
            else if (count_reg >= 3'd0) begin
                shift_reg <= {shift_reg[2:0], d[3]};
            end
        end
    end

    assign valid_out = (count_reg == 3'd3);
    assign dout = shift_reg[0];
