module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);
    reg [3:0] data_reg;
    reg [4:0] counter;
    reg valid_out_reg;
    reg dout_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            valid_out_reg <= 1'b0;
            dout_reg <= 1'b0;
            counter <= 5'd0;
            data_reg <= 4'd0;
        end else begin
            if (counter == 5'd4) begin
                valid_out_reg <= 1'b1;
                dout_reg <= data_reg[0];
                counter <= 5'd0;
                data_reg <= {data_reg[2:0], 1'b0};
            end else begin
                counter <= counter + 5'd1;
                valid_out_reg <= 1'b0;
                dout_reg <= data_reg[0];
                data_reg <= {data_reg[2:0], 1'b0};
            end
        end
    end

    assign valid_out = valid_out_reg;
    assign dout = dout_reg;
endmodule

