module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
     reg [1:0] state;
     reg sequence_detected_reg;

     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             state <= 2'b00;
             sequence_detected_reg <= 1'b0;
         end else begin
             case (state)
                 2'b00: begin
                     if (data_in == 1'b1) state <= 2'b01;
                     else state <= 2'b00;
                 end
                 2'b01: begin
                     if (data_in == 1'b1) state <= 2'b10;
                     else state <= 2'b00;
                 end
                 2'b10: begin
                     if (data_in == 1'b1) begin
                         sequence_detected_reg <= 1'b1;
                         state <= 2'b11;
                     end else begin
                         state <= 2'b00;
                     end
                 end
                 2'b11: begin
                     if (data_in == 1'b1) state <= 2'b11;
                     else state <= 2'b00;
                 end
                 default: state <= 2'b00;
             endcase
         end
     end

     assign sequence_detected = sequence_detected_reg;
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
reg [1:0] state;
reg [1:0] next_state;
reg sequence_detected;
reg previous_bit, previous_previous_bit;

always @ (posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        state <= 2'd0;
        previous_bit <= 1'b0;
        previous_previous_bit <= 1'b0;
    end
    else begin
        state <= next_state;
        previous_bit <= data_in;
        previous_previous_bit <= previous_bit;
    end
end

always @ (*) begin
    case (state)
        2'd0: next_state = (data_in) ? 2'd1 : 2'd0;
        2'd1: next_state = (data_in) ? 2'd2 : 2'd0;
        2'd2: next_state = (data_in) ? 2'd2 : 2'd0;
    default: next_state = 2'd0;
    endcase
end

always @ (*) begin
    if (state == 2'd2) begin
        sequence_detected = 1'b1;
    end
    else begin
        sequence_detected = 1'b0;
    end
end

endmodule

module sequence_detector(
    input  clk, 
    input  rst_n,
    input  data_in, 
    output sequence_detected
);

    reg [2:0] state;
    reg [2:0] next_state;
    reg sequence_detected_reg;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 3'd0;
            sequence_detected_reg <= 1'd0;
        end
        else begin
            state <= next_state;
            sequence_detected_reg <= sequence_detected;
        end
    end

    assign sequence_detected = sequence_detected_reg;

    always @(*) begin
        next_state = state;
        sequence_detected_reg = 1'd0;

        case (state)
            3'd0: if (data_in) next_state = 3'd1;
            3'd1: if (data_in) next_state = 3'd2;
            3'd2: if (data_in) next_state = 3'd0; sequence_detected_reg = 1'd1;
            default: next_state = 3'd0;
        endcase
    end
endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
     wire data_reg, data_reg_1, data_reg_2, data_reg_3, data_reg_4, data_reg_5;
     wire sequence_detected_1, sequence_detected_2, sequence_detected_3, sequence_detected_4;
	reg sequence_detected_5;
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			data_reg <= 1'b0;
			data_reg_1 <= 1'b0;
			data_reg_2 <= 1'b0;
			data_reg_3 <= 1'b0;
			data_reg_4 <= 1'b0;
			data_reg_5 <= 1'b0;
		end
		else begin
		// data_reg always stores the most recent data_in value
			data_reg <= data_in;
		// data_reg_1 stores the second most recent value, and so on
			data_reg_1 <= data_reg;
			data_reg_2 <= data_reg_1;
			data_reg_3 <= data_reg_2;
			data_reg_4 <= data_reg_3;
			data_reg_5 <= data_reg_4;
		end
	end
	assign sequence_detected_1 = (data_reg & data_reg_1 & data_reg_2 & data_reg_3 & data_reg_4);
	assign sequence_detected_2 = (data_reg_1 & data_reg_2 & data_reg_3 & data_reg_4 & data_reg_5);
	assign sequence_detected_3 = (data_reg_2 & data_reg_3 & data_reg_4 & data_reg_5 & data_reg);
	assign sequence_detected_4 = (data_reg_3 & data_reg_4 & data_reg_5 & data_reg & data_reg_1);
	assign sequence_detected_5 = (data_reg_4 & data_reg_5 & data_reg & data_reg_1 & data_reg_2);
	assign sequence_detected = sequence_detected_1 | sequence_detected_2 | sequence_detected_3 | sequence_detected_4 | sequence_detected_5;
endmodule
